    .collect(Collectors.groupingBy(Function.identity(),
        LinkedHashMap::new,          // CRITICAL: preserves insertion order!
        Collectors.counting()));
// "RAJESH" → {R=1, A=1, J=1, E=1, S=1, H=1}  (all unique)
// "BANANA" → {B=1, A=3, N=2}  (LinkedHashMap: B first, A second, N third)

// Step 2: first entry with count == 1
Optional<Character> firstNonRepeating = freq.entrySet().stream()
    .filter(e -> e.getValue() == 1)
    .map(Map.Entry::getKey)
    .findFirst();
// "BANANA" → B (count 1, and it's first in insertion order)

// WHY LinkedHashMap? HashMap might return N before B (random order!)
// LinkedHashMap guarantees: entries iterate in insertion order → B is first
