package com.bank.ifsc.service;

import com.bank.ifsc.dto.CharResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Slf4j
public class CharAnalysisService {

    public CharResult findFirstNonRepeating(String input) {

        // Step 1: frequency map with LinkedHashMap (insertion order preserved)
        Map<Character, Long> freq = input.chars()
            .mapToObj(c -> (char) c)
            .collect(Collectors.groupingBy(
                Function.identity(),      // group by the character itself
                LinkedHashMap::new,       // preserve insertion (appearance) order
                Collectors.counting()));  // count occurrences

        // Step 2: first entry with count == 1
        Optional<Character> firstNonRepeating = freq.entrySet().stream()
            .filter(e -> e.getValue() == 1L)
            .map(Map.Entry::getKey)
            .findFirst();

        log.info("Input: '{}' | Freq: {} | First non-repeating: {}",
            input, freq, firstNonRepeating.orElse(null));

        return new CharResult(input, firstNonRepeating.orElse(null), freq,
            "LinkedHashMap preserves insertion order → findFirst returns the character " +
            "that appeared first in the string AND has count 1");
    }
}
