package com.bank.ifsc.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class FirstNonRepeatingTest {

    private Optional<Character> findFirst(String s) {
        return s.chars().mapToObj(c -> (char) c)
            .collect(Collectors.groupingBy(Function.identity(),
                LinkedHashMap::new, Collectors.counting()))
            .entrySet().stream()
            .filter(e -> e.getValue() == 1L)
            .map(Map.Entry::getKey)
            .findFirst();
    }

    @Test
    void basicCase() {
        assertThat(findFirst("BANANA")).contains('B');  // B=1, A=3, N=2
    }

    @Test
    void allUnique() {
        assertThat(findFirst("RAJESH")).contains('R');  // all count 1, first is R
    }

    @Test
    void allRepeating() {
        assertThat(findFirst("AABB")).isEmpty();  // no count==1
    }

    @Test
    void singleChar() {
        assertThat(findFirst("X")).contains('X');
    }

    @Test
    void emptyString() {
        assertThat(findFirst("")).isEmpty();
    }

    @Test
    void ifscCode() {
        assertThat(findFirst("SBIN0001234")).contains('S');  // S appears once, first position
    }

    @Test
    void linkedHashMapPreservesOrder() {
        // "STRESS" → S=3, T=1, R=1, E=1
        // With LinkedHashMap: T is FIRST non-repeating (position 1 in string)
        // With HashMap: could be T, R, or E (random!)
        assertThat(findFirst("STRESS")).contains('T');
    }
}
